using System.Net.Http; using System.Net.Http.Json; using System.Windows; namespace CloudClient; public partial class MainWindow:Window { readonly HttpClient http=new(); readonly string server; public MainWindow(string url){InitializeComponent();server=url;Loaded+=async(_,__)=>await Load();} async Task Load(){try{var d=await http.GetFromJsonAsync<List<Storage>>(server+"/api/storage")??new();CloudGrid.ItemsSource=d.Select(x=>new Row(x.Name,x.Role,x.QuotaBytes<=0?"Unbegrenzt":x.QuotaBytes>=1099511627776L?$"{x.QuotaBytes/1099511627776d:N2} TB":$"{x.QuotaBytes/1073741824d:N0} GB","Bereit"));}catch(Exception e){MessageBox.Show(e.Message,"Verbindungsfehler");}} sealed class Storage{public string Name{get;set;}="";public string Role{get;set;}="";public long QuotaBytes{get;set;}} sealed record Row(string Name,string Role,string Quota,string Status); }